/// Oracle inventory recorded in the provenance manifest.
pub const TOTAL_BLOCKS: usize = 168;
pub const TOTAL_CASES: usize = 793;
pub const TOTAL_EXECUTIONS: u32 = 1078;
pub const TOTAL_LOCALES: usize = 49;

/// Runs one generated conformance block against the Rust port.
///
/// There is no Rust formatting API before Phase 2, so this deliberately does not
/// exist yet. Every generated test is also `#[ignore]`d, so the placeholder state
/// cannot be mistaken for a pass: `cargo test` reports the blocks as ignored, and
/// `cargo test -- --ignored` panics here on every one of them.
///
/// The panic names every static assertion id the block covers, so a failure
/// points straight at the JavaScript source it came from.
pub fn run(block: &Block) -> ! {
    unimplemented!(
        "generated conformance block {} #{} ({}) is not runnable: {} case(s), {} \
assertion execution(s), assertion id(s) {} -- no Rust implementation until Phase 2 of \
MIGRATION_TO_RUST.md",
        block.file,
        block.test_index,
        block.title,
        block.cases.len(),
        block.executions,
        block.assertion_ids.join(", "),
    )
}
